import random

def luhn_checksum(card_number_without_check_digit):
    digits = [int(d) for d in card_number_without_check_digit]
    # starting from the right, double every second digit
    for i in range(len(digits)-1, -1, -2):
        digits[i] *= 2
        if digits[i] > 9:
            digits[i] -= 9
    return (10 - sum(digits) % 10) % 10

def generate_card_number(prefix, length=16):
    # prefix: string of 1–6 starting digits (e.g. "4" for Visa)
    body_length = length - len(prefix) - 1
    body = ''.join(str(random.randint(0,9)) for _ in range(body_length))
    check_digit = luhn_checksum(prefix + body)
    return prefix + body + str(check_digit)

def generate_cvv(length=3):
    return ''.join(str(random.randint(0,9)) for _ in range(length))

def generate_expiry():
    month = random.randint(1,12)
    year = random.randint(24,30)  # ’24 through ’30
    return f"{month:02d}/{year:02d}"

def generate_fake_cards(n=5):
    card_types = [
      {"name":"Visa","prefix":"4","length":16,"cvv_len":3},
      {"name":"MasterCard","prefix":str(random.choice(range(51,56))),"length":16,"cvv_len":3},
      {"name":"AmEx","prefix":random.choice(["34","37"]),"length":15,"cvv_len":4},
      {"name":"Discover","prefix":"6011","length":16,"cvv_len":3},
